TLM.f("Sancti/07-10",{"officium":"Ss. Septem Fratrum Martyrum, ac Rufinæ et Secundæ Virginum et Martyrum","rule":["vide C3","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 112:1; 112:9"},{"k":"text","la":"Laudáte, púeri, Dóminum, laudáte nomen Dómini: qui habitáre facit stérilem in domo, matrem filiórum lætántem."},{"k":"ref","la":"Ps 112:2"},{"k":"text","la":"Sit nomen Dómini benedíctum: ex hoc nunc, ei usque in sǽculum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Laudáte, púeri, Dóminum, laudáte nomen Dómini: qui habitáre facit stérilem in domo, matrem filiórum lætántem."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui gloriósos Mártyres fortes in sua confessióne cognóvimus, pios apud te in nostra intercessióne sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"rubric","la":"Prov 31:10-31"},{"k":"text","la":"Mulíerem fortem quis invéniet? Procul et de últimis fínibus prétium ejus. Confídit in ea cor viri sui, et spóliis non indigébit. Reddet ei bonum, et non malum, ómnibus diébus vitæ suæ. Quæsívit lanam et linum, et operáta est consílio mánuum suárum. Facta est quasi navis institóris, de longe portans panem suum. Et de nocte surréxit, dedítque prædam domésticis suis, et cibária ancíllis suis. Considerávit agrum, et emit eum: de fructu mánuum suárum plantávit víneam. Accínxit fortitúdine lumbos suos, et roborávit bráchium suum. Gustávit, et vidit, quia bona est negotiátio ejus: non exstinguétur in nocte lucérna ejus. Manum suam misit ad fórtia, et dígiti ejus apprehendérunt fusum. Manum suam apéruit ínopi, et palmas suas exténdit ad páuperem. Non timébit dómui suæ a frigóribus nivis: omnes enim doméstici ejus vestíti sunt duplícibus. Stragulátam vestem fecit sibi: byssus et púrpura induméntum ejus. Nóbilis in portis vir ejus, quando séderit cum senatóribus terræ. Síndonem fecit et véndidit, et cíngulum trádidit Chananǽo. Fortitúdo et decor induméntum ejus, et ridébit in die novíssimo. Os suum apéruit sapiéntiæ, et lex cleméntiæ in lingua ejus. Considerávit sémitas domus suæ, et panem otiósa non comédit. Surrexérunt fílii ejus, et beatíssimam prædicavérunt: vir ejus, et laudávit eam, Multæ fíliæ congregavérunt divítias: tu supergréssa es univérsas. Fallax grátia, et vana est pulchritúdo: múlier timens Dóminum, ipsa laudábitur. Date ei de fructu mánuum suárum: et laudent eam in portis ópera ejus."}],"Graduale":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secuta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secuta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 12:46-50"},{"k":"text","la":"In illo témpore: Loquente Jesu ad turbas, ecce, Mater ejus et fratres stabant foris, quæréntes loqui ei. Dixit autem ei quidam: Ecce, mater tua et fratres tui foris stant, quæréntes te. At ipse respóndens dicénti sibi, ait: Quæ est mater mea et qui sunt fratres mei? Et exténdens manum in discípulos suos, dixit: Ecce mater mea et fratres mei. Quicúmque enim fécerit voluntátem Patris mei, qui in cœlis est: ipse meus frater et soror et mater est."}],"Offertorium":[{"k":"ref","la":"Ps 123:7"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium: láqueus contrítus est, et nos liberáti sumus."}],"Secreta":[{"k":"text","la":"Sacrifíciis præséntibus, quǽsumus, Dómine, inténde placátus: et, intercedéntibus Sanctis tuis, devotióni nostræ profíciant et salúti."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 12:50"},{"k":"text","la":"Quicúmque fécerit voluntátem Patris mei, qui in cœlis est: ipse meus frater et soror et mater est, dicit Dóminus."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, intercedéntibus Sanctis tuis, illíus salutáris capiámus efféctum; cujus per heec mystéria pignus accépimus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"85d8308dca316183":{"t":"Ps 112, 1 i 9, Ps 112, 2\n(Ps 112, 1 i 9) Hvalite, djeco, Gospodina, hvalite ime Gospodnje. On daje da nerotkinja prebiva u kući i čini je majkom koja se veseli djeci. (Ps 112, 2) Bilo ime Gospodnje blagoslivljano od sada i dovijeka.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 112, 1 i 9) Hvalite, djeco, Gospodina, hvalite ime Gospodnje. On daje da nerotkinja prebiva u kući i čini je majkom koja se veseli djeci.","kn":"(Ps. 112, 1, 9). Hvalite, djeco, Gospodina, hvalite Ime Gospodnje, koji daje da nerotkinja prebiva u kući i čini je majkom, koja se veseli djeci. (Ps. 112, 2). Bilo Ime Gospodnje blagosivano, odsada 1 dovijeka. Slava Ocu . . . Hvalite . . .","knRef":"Kniewald 1942, str. 634–635 (snimka 318) (OCR)"},"68887bdeda17172c":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da mi koji smo slavne mučenike upoznali da su bili jaki u svom mučeništvu, osjetimo da su dobrostivi kad nas zagovaraju kod tebe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da mi, koji smo slavne mučenike spoznali neustrašivima u njihovom mučeništvu, . osjetimo njihov blagi zagovor kod Tebe, po G. n.","knRef":"Kniewald 1942, str. 634–635 (snimka 318) (OCR)"},"5057437b8ebed0d6":{"t":"Izr 31, 10-31\nČitanje Knjige mudrosti. Ženu jaku tko da nađe? Cijena je njezina kao stvari donesenih iz daleka, iz krajnih strana zemlje. Pouzdava se u nju srce muža njezina, i neće oskudijevati dobitkom. Vraća mu dobro, a ne zlo sve dane života svoga. Traži vunu i lan i radi vješto svojim rukama. Ona je kao trgovačka lađa koja iz daleka donosi svoj kruh. Ustaje dok je još noć i daje hranu svojim ukućanima i jelo svojim službenicima. Baci oko na njivu i kupi je, nasadi vinograd zaradom svojih ruku. Opasuje snagom bokove svoje i krijepi mišice svoje. S nasladom gleda kako joj posao ide dobro. Noću joj se ne gasi svijeća. Rukama svojim hvata preslicu i prstima svojim uzimlje vreteno. Ruku svoju otvara siromahu i dlane svoje pruža ubogomu. Ne boji se za svoju kuću mraza i snijega, jer svi domaći njezini imaju po dvije haljine. Izvezene pokrivače sebi napravlja, finim platnom i grimizom ona se odijeva. Ugledan je muž njezin kad sjedi na vratima sa starješinama mjesta. Satka tanko platno i prodaje i pojas daje Kananejcu. Jakost i ljepota odijelo je njezino i radovat će se u najposljednji dan. Usta svoja otvara mudro i na jeziku joj je blaga nauka. Pazi kako joj idu kućni poslovi i kruha uzalud ne jede. Sinovi njezini rastu i nazivaju je presretnom i muž je njezin hvali. Mnoge kćeri nakupiše blaga, ali ti ih sve nadvisuješ. Ljupkost je prijevarna i ljepota je tašta. Žena koja se boji Gospodina zaslužuje pohvalu. Dajte joj od ploda njezinih ruku i neka je hvale na vratima njezina djela.","kn":"Čitanje Knjige mudrosti (Pbslov. 31, 10-31). Tko će naći jaku ženu? Na daleko, do krajnik je granica njezina vrijednost. Muževo se srce uzda u nju i ne će oskudjevati dobitkom. Vraćat će mu dobro, a ne zlo sve dane svoga života. Traži vunu i lan J radi svojim vještim rukama. Ona je kao trgovačka lađa, koja izdaleka dovozi svoj kruh. Diže se noću ; daje hranu svojim ukućanima i jelo svojim službenicama. Ogleda njivu i kupi je, nasadi vinograd radom svojih ruku. Opaše snagom svoje bokove i razvije snagu svojih ruku. Okuša i vidi, da je dobar njezin rad, i ne će ,se noću ugasiti njezina svjetiljka. Stavila je svoje ruke na preslicu i njezini su prsti prihvatili vreteno. Otvara svoju desnicu potrebnomu i pruža svoje ruke siromasima. Njezina se kuća ne treba bojati studeni i snijega, jer sve njezina družina ima dvostruke odjeće. Sebi je načinila pokrivač, a odijelo joj je od lana i grimlza. Njezin je muž ugledan, kad sjedi s prvacima zemlje na vratima grada. Satka tanko platno i proda, a tkanicu preda Kananejcu. Obučenai je jakošću i ljepotom, i radovat će sa na sudnji dan. Mudro otvara svoja usta i na jeziku joj je sama blagost. Sama nadzire rad svoje kuće i besiposlena ne jede kruha. Njezini sinovi rastu i nazivaju je presretnom, a hvali je i njezin .muž. Mnoge kćeri sabiru bogatstvo, ali ti nadmašuješ sve. Dražesnost je varava i ljepota je tašta, slavit će se žena, koja se boji Gospodina. Dajte joj od ploda njezinih ruku, i neka je hvalo njezina djela na vratima grada.","knRef":"Kniewald 1942, str. 832–833 (snimka 417) (OCR)"},"b5eef8d62840c3c0":{"t":"Ps 123, 7-8\nDuša se naša kao ptica izbavila iz lovačke zamke. Zamka se raskide i mi se izbavismo. Pomoć je naša u imenu Gospodina koji je stvorio nebo i zemlju.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je pravo bratstvo koje je pobijedilo opačine svijeta, slijedilo je Krista i zadobilo slavno nebesko kraljevstvo. <i>Aleluja</i>.","kn":"(Ps. 123, 7). Duša je naša kao ptica umakla zamki lovčevoj. Zamka se raskide i mi se izbavismo. Pomoć je naša u imenu Gospodnjem, koji stvori nebo i zemlju.\n\nAleluja, aleluja. To je pravo bratstvo, koje je pobijedilo opačine svijeta, slijedeći Krista, zadobilo je kraljevstvo nebesko, aleluja","knRef":"Kniewald 1942, str. 466–467 (snimka 234) (OCR)"},"b76c4879326c2a6d":{"t":"Mt 12, 46-50\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme dok je Isus govorio narodu, čekala je vani njegova majka i braća želeći govoriti s njim. Netko mu javi: Tvoja majka i tvoja braća su vani i čekaju te. A on zapita onoga koji mu je to javio: Tko je moja majka i tko su moja braća? I pruži ruku prema svojim učenicima i reče: Evo moje majke i moje braće! Tko god vrši volju moga Oca, on je moj brat i sestra i majka.","kn":"t Slijedi sv. evanđelje po Mateju (12, 46-50). U ono vrijeme, dok je Isus još govorio silnom svijetu, gle, majka njegova i braća* njegova stajali su na polju želeći, da s njim govore: I netko mu reče: Gle, mati tvoja i braća tvoja stoje napolju i žele s tobom da govore. A on odgovori onomu, koji .mu javi: Tko je mati moja i tko su braća moja? I pruživši svoju ruku na svoje učenike reče: Eto mati moja i braća moja. Jer tkogod čini volju Oca moga, koji . je na nebesima,, on je brat moj i sestra i majka.","knRef":"Kniewald 1942, str. 634–635 (snimka 318) (OCR)"},"420242d00c26cda3":{"t":"Ps 123, 7\nDuša se naša kao ptica izbavila iz lovačke zamke. Zamka se raskide i mi se izbavismo.","kn":"(Ps. 123, 7). Duša je naša kao ptica umakla iz zamke lovačke; zaihka se raskide i mi se izbavismo.","knRef":"Kniewald 1942, str. 466–467 (snimka 234) (OCR)"},"10e5e739a3bb72fe":{"t":"Milostivo pogledaj, molimo, Gospodine, na ove darove, da po zagovoru tvojih svetih neka budu na korist i našoj pobožnosti i spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, molimo Te, milostivo na ove žrtve i podaj, da koriste i našoj pobožnosti i spasenju, po G. n.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"68136dba586ef47a":{"t":"Mt 12, 50\nTko god vrši volju moga nebeskog Oca, on je brat moj i sestra i majka, kaže Gospodin.","kn":"(Mt. 12, 50). Tko čini volju Oca moga, koji je na nebesima, taj je i brat moj i sestra i majka.","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"abf45e68fe9a789e":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da po zagovoru svojih svetih postignemo ono spasenje, kojega smo zalog primili u ovim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, svemogući Bože, da doista postignemo spasenje, kojega smo zalog primili u ovim otajstvima, po G. nr I. K.","knRef":"Kniewald 1942, str. 438–439 (snimka 220) (OCR)"}}});
